using System;using System.Linq;using System.Text;using System.Drawing;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
class BeamDeflectionSummary {
 public string GeometrySource="",ResultSource="",GeometryUnit="",DisplacementUnit="",Vertical="Y",Duration="";public bool ZUp,ServiceBasis,SupportsVerified;public int Nodes,Members;public List<string> Cases=new List<string>();
}
static class BeamDeflectionReport {
 static string F(double v,int d){return v.ToString("F"+d,CultureInfo.InvariantCulture);}
 static string Result(BeamDeflectionResult r){return r.Exceeds?"EXCEEDS":r.Qualified?"OK":r.Status.StartsWith("NOT CHECKED")?"NOT CHECKED":"REVIEW";}
 internal static readonly string[] SummaryHeaders={"Beam","Members","Criterion","Check","L m","Max δ mm","Node","Allowable","δ/δallow","Result"};
 internal static string[] SummaryRow(BeamDeflectionResult r){return new[]{r.Beam,r.Members,r.Criterion,r.Check,F(r.Span,3)+(r.LimitSpan>r.Span+1e-9?" (2L = "+F(r.LimitSpan,3)+")":""),F(r.MaximumMm,2),r.GoverningNode.ToString(CultureInfo.InvariantCulture),"L/"+F(r.LimitRatio,0)+" = "+F(r.LimitMm,2)+" mm",F(r.Utilization,2),Result(r)};}
 internal static readonly string[] ReportHeaders={"Beam","Check","L m","Max δ mm","Node","Allowable mm","L/δ","Result"};
 internal static string[] ReportRow(BeamDeflectionResult r){return new[]{r.Beam,r.Check,F(r.LimitSpan,3),F(r.MaximumMm,2),r.GoverningNode.ToString(CultureInfo.InvariantCulture),"L/"+F(r.LimitRatio,0)+" = "+F(r.LimitMm,2),r.Ratio,Result(r)+" ("+F(r.Utilization,2)+")"};}
 internal static string Text(BeamDeflectionSummary s,List<BeamDeflectionResult> results){var b=new StringBuilder();b.AppendLine("BEAM DEFLECTION CHECK - NSCP 2015 (STAAD.Pro node displacements)");b.AppendLine("Displacements are taken relative to the line joining the displaced supports (cantilever: relative to the fixed support), summed over the listed service load cases.");b.AppendLine("RC: NSCP 2015 Table 424.2.2; λΔ = ξ/(1+50ρ') per Section 424.2.4. Steel/other: NSCP 2015 Chapter 1 deflection limits.");b.AppendLine("Geometry: "+s.GeometrySource+"; unit "+s.GeometryUnit+"; "+s.Nodes+" nodes; "+s.Members+" members.");b.AppendLine("Displacements: "+s.ResultSource+"; unit "+s.DisplacementUnit+"; global "+s.Vertical+"; load cases "+string.Join(", ",s.Cases)+".");b.AppendLine();b.AppendLine(string.Join(" | ",SummaryHeaders));foreach(var r in results)b.AppendLine(string.Join(" | ",SummaryRow(r)));b.AppendLine();
  foreach(var r in results){b.AppendLine(r.Beam+" / "+r.Check+": "+r.Formula+"; "+r.Status);b.AppendLine("Dead cases: "+(r.DeadCases==""?"-":r.DeadCases)+"; live cases: "+(r.LiveCases==""?"-":r.LiveCases));b.AppendLine("Node | x m | δD mm | δL mm | δ mm");foreach(var st in r.Stations)b.AppendLine(st.Node+" | "+F(st.Station,3)+" | "+F(st.Dead,3)+" | "+F(st.Live,3)+" | "+F(st.Relative,3));b.AppendLine();}
  b.AppendLine("Deflections are checked at STAAD analysis nodes only. This record does not constitute engineer approval.");return b.ToString();}
 internal static EngineeringReport Create(BeamDeflectionSummary s,List<BeamDeflectionResult> results){var project=ProjectInfoStore.Read();var report=ProfessionalReport.Create("Beam Deflection Check",project.Name,project.Location,project.Office);report.Subtitle="NSCP 2015 serviceability deflection of beams from STAAD.Pro node displacements";
  int exceed=results.Count(r=>r.Exceeds),review=results.Count(r=>!r.Exceeds&&!r.Qualified);var governing=results.OrderByDescending(r=>r.Utilization).FirstOrDefault();
  report.Highlights.Add(new KeyValuePair<string,string>("Checks",results.Count.ToString(CultureInfo.InvariantCulture)));report.Highlights.Add(new KeyValuePair<string,string>("Exceeding limit",exceed.ToString(CultureInfo.InvariantCulture)));report.Highlights.Add(new KeyValuePair<string,string>("Needs review",review.ToString(CultureInfo.InvariantCulture)));if(governing!=null)report.Highlights.Add(new KeyValuePair<string,string>("Governing δ/δallow",F(governing.Utilization,2)+" ("+governing.Beam+")"));
  var scope=report.Section("Scope and method");
  scope.Paragraph("Serviceability deflection of straight beams modelled in STAAD.Pro, checked against NSCP 2015. A beam may consist of several analysis members joined at intermediate nodes; those nodes are deflection stations, not supports. The global translation normal to the beam axis is used.");
  scope.Equation("Support-chord deflection of one load case:  δ(x) = u(x) − [uA + (uB − uA)·x / L]     (cantilever: δ(x) = u(x) − uA)");
  scope.Equation("Dead / live deflection:  δD(x) = Σ δ(x) over the dead (sustained) cases;   δL(x) = Σ δ(x) over the live cases   (linear superposition)");
  scope.Paragraph("Subtracting the support chord removes rigid-body movement from support settlement or column shortening, so the result is the member's own bending deflection. Dead and live deflections are combined node by node before the maximum is taken.");
  var input=report.Section("STAAD input data");
  input.Table(new[]{"Item","Value"},new[]{
   new[]{"Geometry source",s.GeometrySource==""?"Pasted / typed tables":s.GeometrySource},new[]{"Geometry unit",s.GeometryUnit},new[]{"Nodes / members read",s.Nodes+" / "+s.Members},
   new[]{"Displacement source",s.ResultSource==""?"Pasted / typed table":s.ResultSource},new[]{"Displacement unit",s.DisplacementUnit},
   new[]{"Deflection component","Global "+s.Vertical+(s.ZUp?" (model uses SET Z UP)":"")},new[]{"Load cases available",string.Join(", ",s.Cases)},
   new[]{"Load cases are unfactored service loads",s.ServiceBasis?"Confirmed":"Not confirmed - results marked REVIEW"},new[]{"Support nodes are the real supports",s.SupportsVerified?"Confirmed":"Not confirmed - results marked REVIEW"}});
  var criteria=report.Section("NSCP 2015 deflection criteria");
  criteria.Paragraph("Reinforced concrete - NSCP 2015 Table 424.2.2, maximum permissible calculated deflections:");
  criteria.Table(new[]{"Limit","Member","Deflection to be considered"},new[]{new[]{"L/180","Flat roofs not supporting or attached to nonstructural elements likely to be damaged by large deflections","Immediate deflection due to maximum of Lr, S and R"},new[]{"L/360","Floors not supporting or attached to nonstructural elements likely to be damaged by large deflections","Immediate deflection due to L"},new[]{"L/480","Roof or floor construction supporting or attached to nonstructural elements likely to be damaged by large deflections","That part of the total deflection occurring after attachment of nonstructural elements: sum of the time-dependent deflection due to all sustained loads and the immediate deflection due to any additional live load"},new[]{"L/240","Roof or floor construction supporting or attached to nonstructural elements not likely to be damaged by large deflections","As above"}});
  criteria.Equation("λΔ = ξ / (1 + 50ρ')    NSCP 2015 Section 424.2.4.1.1;  ξ from Table 424.2.4.1.3 (5 years or more 2.0, 12 months 1.4, 6 months 1.2, 3 months 1.0)");
  criteria.Paragraph("ρ' is the compression reinforcement ratio As'/(b·d) at midspan for simple and continuous spans and at the support for cantilevers. Immediate deflections must use the effective moment of inertia Ie (Section 424.2.3). When the STAAD model uses gross section stiffness Ig, the immediate deflections are multiplied by the entered ratio Ig/Ie; enter 1.0 when STAAD stiffness already represents the cracked/effective section. After-attachment deflection is taken conservatively as λΔ·δD,i + δL,i (all sustained load is assumed to act after attachment).");
  criteria.Paragraph("Steel and other members - NSCP 2015 Chapter 1 member deflection limits:");
  criteria.Table(new[]{"Construction","Live load L","Dead + live D + L"},new[]{new[]{"Floor members","L/360","L/240"},new[]{"Roof members supporting plaster or stucco ceiling","L/360","L/240"},new[]{"Roof members supporting nonplaster ceiling","L/240","L/180"},new[]{"Roof members not supporting ceiling","L/180","L/120"}});
  criteria.Note("For steel/other cantilevers, L is taken as twice the cantilever length. For RC cantilevers L is the cantilever length. Where the project specification is stricter, use the Custom limit.");
  var applied=report.Section("Criteria and parameters applied per beam");
  applied.Table(new[]{"Beam","Criterion","Dead / sustained cases","Live cases","Parameters"},results.GroupBy(r=>r.Beam+"\u0001"+r.Members).Select(g=>{var r=g.First();return new[]{r.Beam+" ("+r.Members+")",r.Criterion,r.DeadCases==""?"-":r.DeadCases,r.LiveCases==""?"-":r.LiveCases,r.Criterion.StartsWith("RC")?"ξ = "+F(r.Xi,1)+", ρ' = "+F(r.RhoPrime,4)+", λΔ = "+F(r.Lambda,3)+", Ig/Ie = "+F(r.StiffnessFactor,2):r.Criterion==BeamDeflection.Custom?"L/"+F(r.LimitRatio,0):"-"};}));
  var summary=report.Section("Summary of checks");summary.Table(ReportHeaders,results.Select(ReportRow));
  summary.Note("OK = within the limit at every analysis node with load basis and supports confirmed. REVIEW = within the limit but a confirmation is pending. NOT CHECKED = no intermediate node between the supports. EXCEEDS = the limit is exceeded.");
  foreach(var group in results.GroupBy(r=>r.Beam+"\u0001"+r.Members)){var first=group.First();var section=report.Section("Beam "+first.Beam+" - members "+first.Members);
   section.Paragraph("Supports: node "+first.StartNode+" (A) to node "+first.EndNode+" (B). "+(first.SpanType==BeamDeflection.Cantilever?"Cantilever length":"Span")+" = "+F(first.Span,3)+" m with "+(first.Stations.Count-2)+" intermediate node(s); largest node spacing "+F(first.LargestSegment,3)+" m. Criterion: "+string.Join("; ",group.Select(r=>r.Criterion+" ("+r.Clause+")").Distinct())+".");
   foreach(var ieRow in group.Where(r=>r.IeBasis!="").GroupBy(r=>r.IeBasis).Select(x=>x.First())){var ii=EffectiveInertia.Parse(ieRow.IeBasis);var ir=EffectiveInertia.Calculate(ii);section.Paragraph("Effective moment of inertia, NSCP 2015 Section 424.2.3.5 (rectangular section, cracked transformed section with compression steel):");section.Table(new[]{"Step","Value","Calculation"},EffectiveInertia.Rows(ii,ir));if(Math.Abs(ir.Ratio-ieRow.StiffnessFactor)>.005||Math.Abs(ir.RhoPrime-ieRow.RhoPrime)>5e-6)section.Note("The Ig/Ie or ρ' used ("+F(ieRow.StiffnessFactor,3)+", "+F(ieRow.RhoPrime,5)+") differs from this derivation ("+F(ir.Ratio,3)+", "+F(ir.RhoPrime,5)+"). The values used in the check are those entered on the sheet.");}
   section.Table(new[]{"Node","x m","δD mm","δL mm"}.Concat(group.Select(r=>r.Check+" δ mm")).ToArray(),first.Stations.Select((st,i)=>new[]{st.Node.ToString(CultureInfo.InvariantCulture),F(st.Station,3),F(st.Dead,3),F(st.Live,3)}.Concat(group.Select(r=>F(r.Stations[i].Relative,3))).ToArray()));
   foreach(var r in group){var g=r.Stations.First(st=>st.Node==r.GoverningNode);
    section.Equation(r.Check+":  "+r.Formula+"\nAt node "+g.Node+" (x = "+F(g.Station,3)+" m):  δ = "+F(r.DeadFactor,3)+" × ("+F(g.Dead,3)+") + "+F(r.LiveFactor,3)+" × ("+F(g.Live,3)+") = "+F(g.Relative,3)+" mm\n|δ| = "+F(r.MaximumMm,2)+" mm  vs  L/"+F(r.LimitRatio,0)+" = "+F(r.LimitSpan*1000,0)+" / "+F(r.LimitRatio,0)+" = "+F(r.LimitMm,2)+" mm   →  "+r.Ratio+",  δ/δallow = "+F(r.Utilization,2));
    section.Note(r.Status);}
   section.Figure(Svg(group.OrderByDescending(r=>r.Utilization).First()),"Governing deflected shape relative to the support chord - "+first.Beam+" (vertical scale exaggerated; shaded band = allowable)",true);}
  var limits=report.Section("Limitations and review notes");
  limits.Paragraph("Deflections are evaluated at STAAD analysis nodes only. A maximum between nodes is not captured; where the node spacing is a large part of the span, add intermediate nodes in STAAD (for example at quarter or tenth points) and re-run the analysis.");
  limits.Paragraph("The check depends on the STAAD model, member releases, section stiffness, load cases and units supplied. Confirm that the listed cases are unfactored service loads, that dead and live cases are not double counted, and that Support A and Support B are the real supports. For reinforced concrete, confirm the Ig/Ie ratio and ρ' used.");
  limits.Paragraph("This calculation record is generated from the imported data. It is not an engineer's approval or signature and should be reviewed before issue.");
  return report;}
 internal static string Svg(BeamDeflectionResult r){double w=760,h=190,left=50,right=30,mid=86;double scaleX=(w-left-right)/Math.Max(r.Span,1e-9);double peak=Math.Max(r.Stations.Max(s=>Math.Abs(s.Relative)),Math.Max(r.LimitMm,1e-6));double scaleY=66/peak;Func<double,double> X=x=>left+x*scaleX;Func<double,double> Y=v=>mid-v*scaleY;var b=new StringBuilder();
  b.Append("<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 "+F(w,0)+" "+F(h,0)+"' width='100%' font-family='Arial' font-size='11'>");
  b.Append("<rect x='"+F(left,1)+"' y='"+F(Y(r.LimitMm),1)+"' width='"+F(w-left-right,1)+"' height='"+F(2*r.LimitMm*scaleY,1)+"' fill='#e8f3f1'/>");
  b.Append("<line x1='"+F(left,1)+"' y1='"+F(mid,1)+"' x2='"+F(w-right,1)+"' y2='"+F(mid,1)+"' stroke='#7b8794' stroke-width='1.5'/>");
  b.Append("<polyline fill='none' stroke='"+(r.Exceeds?"#b42318":"#0f6e6e")+"' stroke-width='2.2' points='"+string.Join(" ",r.Stations.Select(s=>F(X(s.Station),1)+","+F(Y(s.Relative),1)))+"'/>");
  foreach(var s in r.Stations){b.Append("<circle cx='"+F(X(s.Station),1)+"' cy='"+F(Y(s.Relative),1)+"' r='3' fill='#213b57'/>");b.Append("<text x='"+F(X(s.Station),1)+"' y='"+F(h-36,1)+"' text-anchor='middle' fill='#526174'>"+s.Node+"</text>");}
  bool cant=r.SpanType==BeamDeflection.Cantilever;b.Append("<path d='M"+F(left,1)+" "+F(mid,1)+" l-9 16 h18 z' fill='#213b57'/>");if(!cant)b.Append("<path d='M"+F(w-right,1)+" "+F(mid,1)+" l-9 16 h18 z' fill='#213b57'/>");else b.Append("<rect x='"+F(left-14,1)+"' y='"+F(mid-26,1)+"' width='6' height='52' fill='#213b57'/>");
  var g=r.Stations.First(s=>s.Node==r.GoverningNode);b.Append("<text x='"+F(Math.Min(w-150,Math.Max(left+5,X(g.Station)+6)),1)+"' y='"+F(Y(g.Relative)+(g.Relative<0?16:-8),1)+"' fill='#202d3c' font-weight='bold'>"+F(g.Relative,2)+" mm</text>");
  b.Append("<text x='"+F(left,1)+"' y='"+F(h-12,1)+"' fill='#526174'>"+EngineeringReport.Escape(r.Check)+" | A (node "+r.StartNode+") | L = "+F(r.Span,3)+" m | band = ±"+F(r.LimitMm,2)+" mm</text>");
  b.Append("<text x='"+F(w-right,1)+"' y='"+F(h-12,1)+"' text-anchor='end' fill='#526174'>"+(cant?"free end":"B (node "+r.EndNode+")")+"</text></svg>");return b.ToString();}
 // Drawn PDF/print pages for the governing deflected shape of each beam (3 per page).
 internal static void AddShapeSheets(CalculationDocument document,List<BeamDeflectionResult> results){var governing=results.GroupBy(r=>r.Beam+"\u0001"+r.Members).Select(g=>g.OrderByDescending(r=>r.Utilization).First()).ToList();for(int i=0;i<governing.Count;i+=3){var page=governing.Skip(i).Take(3).ToList();document.Sheets.Add(g=>{PdfBrand.Draw(g);CalculationDocument.Section(g,"GOVERNING DEFLECTED SHAPES RELATIVE TO SUPPORT CHORD",40);float top=80;foreach(var r in page){Shape(g,r,36,top,523,230);top+=245;}});}}
 static void Shape(Graphics g,BeamDeflectionResult r,float x0,float y0,float width,float height){CalculationDocument.Text(g,r.Beam+" - "+r.Check+"  |  L = "+F(r.Span,3)+" m  |  max |δ| = "+F(r.MaximumMm,2)+" mm at node "+r.GoverningNode+"  |  allowable L/"+F(r.LimitRatio,0)+" = "+F(r.LimitMm,2)+" mm  |  "+Result(r),x0,y0,width,30,8,true);
  float left=x0+24,right=x0+width-16,mid=y0+105;float scaleX=(float)((right-left)/Math.Max(r.Span,1e-9));double peak=Math.Max(r.Stations.Max(s=>Math.Abs(s.Relative)),Math.Max(r.LimitMm,1e-6));float scaleY=(float)(60/peak);
  using(var band=new SolidBrush(Color.FromArgb(232,243,241)))g.FillRectangle(band,left,mid-(float)r.LimitMm*scaleY,right-left,(float)(2*r.LimitMm*scaleY));
  using(var axis=new Pen(Color.FromArgb(123,135,148),1f))g.DrawLine(axis,left,mid,right,mid);
  var points=r.Stations.Select(s=>new PointF(left+(float)s.Station*scaleX,mid-(float)s.Relative*scaleY)).ToArray();using(var pen=new Pen(r.Exceeds?Color.FromArgb(180,35,24):Color.FromArgb(15,110,110),1.8f))if(points.Length>1)g.DrawLines(pen,points);
  using(var dot=new SolidBrush(Color.FromArgb(33,59,87))){foreach(var p in points)g.FillEllipse(dot,p.X-2.2f,p.Y-2.2f,4.4f,4.4f);g.FillPolygon(dot,new[]{new PointF(left,mid),new PointF(left-7,mid+12),new PointF(left+7,mid+12)});if(r.SpanType!=BeamDeflection.Cantilever)g.FillPolygon(dot,new[]{new PointF(right,mid),new PointF(right-7,mid+12),new PointF(right+7,mid+12)});}
  for(int i=0;i<r.Stations.Count;i++)if(r.Stations.Count<=24||i%Math.Max(1,r.Stations.Count/12)==0||i==r.Stations.Count-1)CalculationDocument.Text(g,r.Stations[i].Node.ToString(CultureInfo.InvariantCulture),points[i].X-14,mid+70,28,14,7);
  CalculationDocument.Text(g,"Node numbers along the beam; shaded band = ±allowable; vertical scale exaggerated.",x0,y0+height-24,width,14,7);}
}
}
